//  (scot %uw (jam [~sampel-palnet 3 sec:ex:sp ~]))
//
static const c3_c* seed_uw_c =
  "0w2UW3e.v6ijs.3qNHZ.V-m6i.DYAd~.LAuxL.CYqV1.-dXwZ.PVpAz.Uiw8y.rsjcp."
  "cVb-r.QvdM8.h3ruM.WhYmc.yVRt4.~nkLR.pgwd0.0W71J.u9~Y1\n";

static c3_z
_vec(const c3_c* nam_c, c3_y* out_y, c3_z cap_z)
{
  for ( c3_z i_z = 0; i_z < sizeof(vec_u) / sizeof(vec_u[0]); i_z++ ) {
    if ( 0 == strcmp(nam_c, vec_u[i_z].nam_c) ) {
      const c3_c* hex_c = vec_u[i_z].hex_c + 2;
      c3_z        len_z = strlen(hex_c);

      memset(out_y, 0, cap_z);
      for ( c3_z j_z = 0; j_z < len_z; j_z++ ) {
        c3_c c = hex_c[len_z - 1 - j_z];
        c3_y v = ( c <= '9' ) ? c - '0' : c - 'a' + 10;
        u3_assert( j_z / 2 < cap_z );
        out_y[j_z / 2] |= v << (4 * (j_z & 1));
      }
      return mesa_met3_bytes((len_z + 1) / 2, out_y);
    }
  }
  u3_assert(!"no such vector");
}

static void
_check(const c3_c* nam_c, c3_z len_z, const c3_y* hav_y)
{
  c3_y wan_y[256];
  c3_z wan_z = _vec(nam_c, wan_y, sizeof(wan_y));
  c3_z hav_z = mesa_met3_bytes(len_z, hav_y);

  if ( (wan_z != hav_z) || memcmp(wan_y, hav_y, wan_z) ) {
    fprintf(stderr, "ident: %s mismatch\r\n", nam_c);
    ret_i = 1;
  }
}

static void
_expect(c3_t ok_t, const c3_c* msg_c)
{
  if ( !ok_t ) {
    fprintf(stderr, "ident: %s\r\n", msg_c);
    ret_i = 1;
  }
}

static c3_t
_ide_eq(const mesa_ident* a, const mesa_ident* b)
{
  return mesa_ship_eq(a->who, b->who) && (a->rift == b->rift)
      && (a->life == b->life) && !memcmp(a->ring, b->ring, 65);
}

static mesa_ship
_ship(const c3_c* str_c)
{
  mesa_ship who;
  u3_assert( mesa_ship_parse(str_c, &who) );
  return who;
}

static void
_test_sha(void)
{
  c3_y out_y[64];
  c3_y buf_y[208];

  mesa_shax(3, (const c3_y*)"abc", out_y);
  _check("shax-abc", 32, out_y);

  mesa_shax(0, 0, out_y);
  _check("shax-empty", 32, out_y);

  memset(buf_y, 'a', 200);
  mesa_shay(200, buf_y, out_y);
  _check("shay-long", 32, out_y);

  mesa_shal(3, (const c3_y*)"abc", out_y);
  _check("shal-abc", 64, out_y);

  mesa_shas(4, (const c3_y*)"bfig", 5, (const c3_y*)"hello", out_y);
  _check("shas", 32, out_y);

  mesa_shaf(4, (const c3_y*)"bfig", 5, (const c3_y*)"hello", out_y);
  _check("shaf", 16, out_y);

  //  every padding boundary, against a straightforward sha-256 identity:
  //  hashing the same bytes through shax with trailing zeros trimmed
  //
  for ( c3_z len_z = 0; len_z < 200; len_z++ ) {
    c3_y one_y[32], two_y[32];
    memset(buf_y, 0, sizeof(buf_y));
    memset(buf_y, 'x', len_z);
    mesa_shay(len_z, buf_y, one_y);
    mesa_shax(len_z + 3, buf_y, two_y);
    _expect(0 == memcmp(one_y, two_y, 32), "shax trims zeros");
  }
}

static void
_test_fake(void)
{
  mesa_ident ide;
  c3_y       pas_y[65];

  mesa_ident_fake(_ship("~zod"), &ide);
  _check("zod-ring", 65, ide.ring);
  mesa_ident_pass(&ide, pas_y);
  _check("zod-pass", 65, pas_y);
  _expect(0 == ide.rift && 1 == ide.life, "fake rift/life");

  mesa_ident_fake(_ship("~nec"), &ide);
  mesa_ident_pass(&ide, pas_y);
  _check("nec-pass", 65, pas_y);

  mesa_ident_fake(_ship("~sampel-palnet"), &ide);
  mesa_ident_pass(&ide, pas_y);
  _check("sp-pass", 65, pas_y);
}

static void
_test_comet(void)
{
  mesa_ident ide = {0};
  c3_y       pas_y[65], fig_y[16], wan_y[16];
  mesa_ship  who;

  _vec("comet-a-ring", ide.ring, 65);
  mesa_ident_pass(&ide, pas_y);
  _check("comet-a-pass", 65, pas_y);

  _vec("comet-a", wan_y, 16);
  memcpy(&who.lo, wan_y, 8);
  memcpy(&who.hi, wan_y + 8, 8);
  _expect(mesa_comet_check(who, pas_y), "comet-a checks");

  //  wrong key
  //
  {
    c3_y bad_y[65];
    memcpy(bad_y, pas_y, 65);
    bad_y[7] ^= 1;
    _expect(!mesa_comet_check(who, bad_y), "comet-a forged key");
  }

  //  mine under two stars, then verify
  //
  {
    mesa_ship stars[2] = { _ship("~marzod"), _ship("~binzod") };
    c3_y      eny_y[64];
    char*     who_c;

    for ( c3_w i = 0; i < 64; i++ ) eny_y[i] = (c3_y)(i * 7 + 1);
    _expect(mesa_comet_mine(2, stars, eny_y, 1000000, &ide), "mine comet");
    _expect(MESA_PAWN == mesa_ship_rank(ide.who), "mined a comet");
    _expect(  mesa_ship_eq(stars[0], mesa_ship_sein(ide.who))
           || mesa_ship_eq(stars[1], mesa_ship_sein(ide.who)),
           "mined under a listed star");
    mesa_ident_pass(&ide, pas_y);
    _expect(mesa_comet_check(ide.who, pas_y), "mined comet checks");

    who_c = mesa_ship_render(ide.who);
    fprintf(stderr, "ident: mined %s\r\n", who_c);
    c3_free(who_c);

    //  round-trip through a keyfile
    //
    {
      char*      key_c = mesa_keyfile_render(&ide);
      mesa_ident out_u[2];

      _expect(1 == mesa_keyfile_parse(key_c, out_u, 2), "comet keyfile");
      _expect(_ide_eq(&ide, &out_u[0]), "comet keyfile rt");
      c3_free(key_c);
    }

    //  a galaxy is not a star
    //
    stars[1] = _ship("~zod");
    _expect(!mesa_comet_mine(2, stars, eny_y, 10, &ide), "reject galaxy");
  }
  (void)fig_y;
}

static void
_test_keyfile(void)
{
  mesa_ident ide[4];
  mesa_ident fak;
  c3_y       pas_y[65];

  //  +seed:jael
  //
  _expect(1 == mesa_keyfile_parse(seed_uw_c, ide, 4), "parse seed");
  _expect(mesa_ship_eq(ide[0].who, _ship("~sampel-palnet")), "seed who");
  _expect(3 == ide[0].life, "seed life");
  _expect(MESA_RIFT_UNKNOWN == ide[0].rift, "seed rift");
  mesa_ident_pass(&ide[0], pas_y);
  _check("sp-pass", 65, pas_y);

  //  rendering produces the [%2 ~] feed; compare against Hoon's jam
  //
  {
    c3_y       jam_y[256], wan_y[256];
    c3_z       wan_z = _vec("jam-feed2", wan_y, sizeof(wan_y));
    mesa_ident two   = ide[0];
    char*      key_c;
    c3_z       len_z;
    mesa_noun  fed;
    c3_y*      out_y;

    two.rift = 4;
    key_c = mesa_keyfile_render(&two);
    _expect(1 == mesa_keyfile_parse(key_c, ide, 4), "parse feed");
    _expect(4 == ide[0].rift && 3 == ide[0].life, "feed rift/life");

    //  re-jam what we parsed
    //
    {
      c3_y who_y[16] = {0};
      memcpy(who_y, &two.who.lo, 8);
      memcpy(who_y + 8, &two.who.hi, 8);
      fed = mesa_qual(mesa_cell(mesa_atom_u64(2), mesa_atom_u64(0)),
                      mesa_atom_bytes(16, who_y),
                      mesa_atom_u64(4),
                      mesa_cell(mesa_cell(mesa_atom_u64(3),
                                          mesa_atom_bytes(65, two.ring)),
                                mesa_atom_u64(0)));
      out_y = mesa_jam_bytes(fed, &len_z);
      _expect((len_z == wan_z) && !memcmp(out_y, wan_y, wan_z), "jam-feed2");
      c3_free(out_y);
      mesa_unref(fed);
    }
    c3_free(key_c);
    (void)jam_y;
  }

  //  junk
  //
  _expect(-1 == mesa_keyfile_parse("", ide, 4), "empty");
  _expect(-1 == mesa_keyfile_parse("0w", ide, 4), "no digits");
  _expect(-1 == mesa_keyfile_parse("0x1234", ide, 4), "not uw");
  _expect(-1 == mesa_keyfile_parse("0w1.2!3", ide, 4), "bad digit");
  _expect(-1 == mesa_keyfile_parse("0w5", ide, 4), "not a feed");

  //  fake identity survives a keyfile
  //
  mesa_ident_fake(_ship("~marzod"), &fak);
  {
    char* key_c = mesa_keyfile_render(&fak);
    _expect(1 == mesa_keyfile_parse(key_c, ide, 4), "fake keyfile");
    _expect(_ide_eq(&fak, &ide[0]), "fake keyfile rt");
    c3_free(key_c);
  }
}

int
main(int argc, char* argv[])
{
  _test_sha();
  _test_fake();
  _test_comet();
  _test_keyfile();

  if ( ret_i ) {
    fprintf(stderr, "ident: failed\r\n");
  }
  else {
    fprintf(stderr, "ident ok\r\n");
  }
  return ret_i;
}
